import { generateAIResponse } from './provider.js';

export async function generateBranchName(task: string) {
  const prompt = `Create a short, kebab-case git branch name for task: ${task}`;
  const raw = await generateAIResponse(prompt);
  return raw.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'feature-update';
}
